const lessons = [];
function add(track, id, title, summary, explanation, steps, example, practice, criteria, pitfalls, questions) {
  lessons.push({track,id,title,summary,explanation,steps:steps.split('|'),example,practice,criteria:criteria.split('|'),pitfalls:pitfalls.split('|'),questions:questions.split('|')});
}

add('role','mandate','Что делает тимлид','Ответственность, полномочия и границы роли.',
  'Тимлид отвечает за способность команды регулярно приносить полезный результат. Он соединяет инженерные решения, развитие людей и договорённости с продуктом. В разных компаниях часть кадровых решений может принадлежать менеджеру, а архитектурных — техлиду: название роли не заменяет письменного соглашения о полномочиях. Личная скорость написания кода больше не является главным показателем успеха.',
  'Запишите результат, за который команда отвечает, и назовите заказчика этого результата.|Согласуйте с руководителем, какие решения вы принимаете сами: приоритеты, технический выбор, найм, отпуска, оценка работы.|Отметьте зоны, где нужно согласование, и владельца окончательного решения.|Сообщите команде, как к вам обращаться за помощью и какие решения остаются у участников.',
  'Команда отвечает за оформление заказа. Продакт выбирает ценность и сроки на уровне продукта, тимлид отвечает за реализуемый план и качество поставки, инженер предлагает технический способ. При конфликте дат и объёма они вместе выбирают компромисс.',
  'Составьте одностраничную карту роли для своей или учебной команды: цели, решения, ограничения, заинтересованные стороны и границы ответственности.',
  'Есть измеримый результат команды|Для каждого спорного решения указан владелец|Границы согласованы с руководителем и командой',
  'Принимать все решения лично и стать узким местом|Считать себя начальником без ясных полномочий|Продолжать оценивать себя только количеством собственного кода',
  'Чем результат команды отличается от суммы личных задач?|Как поступить, если ответственность есть, а права принимать решение нет?');

add('role','first-90','Первые 90 дней','Диагностика, доверие и первые улучшения.',
  'Первые недели нужны для понимания системы, а не для демонстрации силы. До реформ выясните, что работает, какие обещания даны, где болит и кто принимает решения. Улучшение должно решать наблюдаемую проблему, иметь владельца и способ проверки. Слишком много перемен одновременно лишают команду возможности понять эффект.',
  'В первые две недели проведите индивидуальные встречи, изучите продукт, инциденты, поток задач и существующие договорённости.|Сформулируйте 3–5 гипотез о препятствиях и проверьте их данными и разговорами.|Выберите одно небольшое изменение с высокой пользой и обратимостью.|На 30-й, 60-й и 90-й день обсудите результат с командой и руководителем, обновите план.',
  'Новый лид увидел много просроченных задач и хотел немедленно заменить процесс. Разговоры показали, что основная причина — внезапные срочные запросы от поддержки. Команда сначала ввела явный канал и лимит для таких запросов.',
  'Напишите план 30/60/90: кого спросить, какие документы прочитать, какие показатели посмотреть и какое одно изменение проверить.',
  'План отделяет наблюдения от гипотез|Есть встречи с командой и смежниками|Для первого изменения указан сигнал успеха и дата пересмотра',
  'Объявлять новый процесс до диагностики|Обещать мгновенный рост скорости|Игнорировать неформальные договорённости',
  'Что вы должны узнать раньше первого изменения?|Как заметить, что улучшение не сработало?');

add('role','team-system','Команда как система','Роли, зависимости и устойчивость.',
  'Результат зависит не только от сильных специалистов. Важны ясные цели, распределение знаний, правила взаимодействия и доступ к решениям. Если только один человек может выпустить сервис, команда уязвима даже при хорошем среднем темпе. Тимлид видит такие зависимости и создаёт условия, в которых специалисты могут самостоятельно работать.',
  'Нарисуйте путь задачи от идеи до эксплуатации: кто участвует и где возникает ожидание.|Составьте карту критичных знаний и проверьте, у каких областей один владелец.|Выберите способ снизить зависимость: парная работа, документация, ротация, обучение.|Закрепите правила эскалации, ревью и подмены на время отсутствия.',
  'В продуктовой команде релизы держались на одном опытном инженере. За месяц два разработчика провели совместные релизы с ним, записали процедуру и выполнили следующий релиз самостоятельно.',
  'Создайте карту команды: роли, зоны владения, зависимые люди, ключевые риски и два действия для повышения устойчивости.',
  'Обозначены точки, где работа останавливается без конкретного человека|У каждого риска есть действие и срок|Команда понимает правила эскалации',
  'Путать распределение ответственности с жёсткими должностными границами|Хранить знания только в голове эксперта|Подменять помощь постоянным контролем',
  'Что случится, если ключевой инженер уйдёт в отпуск?|Какие решения команда должна принимать без вас?');

add('product','value','Ценность и результат продукта','Связать инженерную работу с пользовательской проблемой.',
  'Бэклог не является стратегией. Сначала нужно понять, кому и какую проблему решает продукт, каким поведением пользователя виден успех и какие ограничения есть у бизнеса. Метрика результата может отставать от изменений, поэтому полезно иметь и ранние сигналы. Тимлид помогает оценить осуществимость, стоимость поддержки и риски решения.',
  'Опишите сегмент пользователей и конкретную проблему без названия функции.|Согласуйте с продактом ожидаемое изменение поведения и показатель результата.|Перечислите допущения: что неизвестно о спросе, технологии и сроках.|Выберите минимальную проверку и дату, когда команда посмотрит на результат.',
  'Фраза «добавить чат» заменена задачей «снизить время решения вопроса о заказе». Анализ показал, что большинство обращений решается точным статусом заказа; команда начала с этого изменения.',
  'Для одной функции напишите цепочку: проблема → пользователь → гипотеза → изменение поведения → показатель → способ проверки.',
  'Проблема описана словами пользователя|Показатель относится к результату, а не числу функций|Есть дешёвая проверка рискованного допущения',
  'Начинать обсуждение с технологии|Приравнивать выпущенную функцию к полученной ценности|Выбирать показатель, на который команда не может повлиять',
  'Кто получит пользу от этой работы?|Как вы узнаете, что гипотеза оказалась неверной?');

add('product','priorities','Приоритеты и отказ от лишнего','Сравнивать ценность, срочность, стоимость и риск.',
  'Приоритет означает порядок расходования ограниченной мощности команды. У срочного запроса должна быть причина: потеря денег, нарушение обещания, риск безопасности или критичный пользовательский ущерб. Для остальных задач сравнивайте ожидаемую пользу, усилия, неопределённость и стоимость промедления. Любое добавление в план требует явного ответа, что откладывается.',
  'Соберите все конкурирующие задачи в один видимый список.|Для каждой укажите пользу, срок, стоимость, риск и степень уверенности оценки.|Разделите обязательные работы, эксперименты, поддержание системы и пожелания.|Согласуйте порядок с продактом и заинтересованными сторонами; опубликуйте причины и пересматривайте при новых данных.',
  'Срочный запрос партнёра добавили в середине итерации. Лид показал, что команда переносит интеграцию на неделю, а не обещает сделать обе задачи прежним составом и в прежний срок.',
  'Возьмите шесть вымышленных задач, расположите по порядку и запишите для каждой причину. Затем добавьте экстренную задачу и явно укажите, что вытесняется.',
  'У всех задач есть понятное основание порядка|Переключение отражено в сроках или объёме|Есть правило для действительно экстренных работ',
  'Называть всё срочным|Скрывать стоимость переключения|Оценивать приоритет только голосованием или должностью инициатора',
  'Что команда перестанет делать ради новой задачи?|Какая информация может изменить текущий порядок?');

add('product','discovery','Работа с неопределённостью','Разделять исследование и обязательство по поставке.',
  'Неизвестное нельзя надёжно оценить как обычную реализацию. Технический прототип, интервью и небольшое измерение помогают ограничить риск до большого вложения. Исследование должно иметь вопрос, временную рамку и решение по итогам; бесконечное «изучить тему» не даёт результата. После проверки команда пересматривает объём и сроки.',
  'Назовите три главные неизвестные: ценность, технология, данные, юридические условия или зависимости.|Для каждой придумайте самый дешёвый способ получить ответ.|Ограничьте время проверки и запишите критерий продолжения или отказа.|После проверки обновите план и объясните, какие допущения изменились.',
  'Перед переносом расчётов на новый движок команда за два дня проверила пиковую нагрузку на обезличенных данных. Результат выявил дорогой запрос; проектное решение изменили до полной миграции.',
  'Составьте карточку исследования: вопрос, гипотеза, эксперимент, лимит времени, критерий решения и следующее действие.',
  'Эксперимент отвечает на один важный вопрос|Есть предел затрат времени|Указано решение для положительного и отрицательного результата',
  'Выдавать прототип за готовую систему|Планировать неизвестное с ложной точностью|Продолжать исследование без решения',
  'Какую неопределённость выгоднее снять первой?|Как изменится план при отрицательном результате?');

add('planning','slicing','Декомпозиция и вертикальные срезы','Делать задачи проверяемыми и поставляемыми.',
  'Большая задача скрывает зависимости и поздно даёт обратную связь. Разделяйте работу на небольшие пользовательские или системные результаты, которые можно проверить отдельно. Слой «сделать базу» сам по себе не доказывает ценность; вертикальный срез проходит через необходимые части системы и заканчивается наблюдаемым поведением.',
  'Сформулируйте критерий завершения результата и основные сценарии.|Разделите работу по сценариям, группам пользователей, условиям или уровню автоматизации.|Для каждого среза укажите зависимости, тест и способ безопасного включения.|Проверьте, что задачу можно показать или измерить без завершения всех остальных срезов.',
  'Оплату разделили на первую успешную транзакцию для одной валюты, обработку отказа, возвраты и сверку. Первый срез позволил проверить интеграцию до полного объёма.',
  'Разбейте крупную функцию минимум на четыре среза. Для каждого напишите демонстрацию результата и критерий приёмки.',
  'Каждый срез даёт проверяемое поведение|Зависимости названы|Первые срезы снимают наиболее опасные допущения',
  'Дробить только по техническим слоям|Создавать задачи без критерия завершения|Оставлять интеграцию на последний день',
  'Можно ли показать результат первого среза?|Что узнает команда после его выпуска?');

add('planning','forecast','Оценка и прогноз','Обещать срок как диапазон с предпосылками.',
  'Оценка — инструмент принятия решения, а не гарантия. Укажите объём, известные зависимости, доступность людей и неопределённость. Историческая скорость поставки помогает больше, чем точность отдельных чисел. Разделяйте дату обязательства, текущий прогноз и степень уверенности; пересматривайте прогноз по мере появления фактов.',
  'Опишите состав результата и явно исключённые части.|Посмотрите на похожие завершённые задачи или пропускную способность команды.|Определите диапазон, главные риски и резерв на интеграцию и проверку.|На каждой контрольной точке сопоставляйте фактическое завершение с прогнозом и сообщайте изменение заранее.',
  'Команда ожидала выпустить интеграцию за 4–6 недель при готовом API партнёра. На второй неделе стало ясно, что контракт меняется. Лид сразу предложил сузить первый релиз или сдвинуть дату.',
  'Составьте прогноз для проекта из пяти срезов: диапазон срока, допущения, три риска, дата пересмотра и два варианта уменьшения объёма.',
  'Диапазон связан с историческими данными или явными допущениями|Риски видны заказчику|Есть правило раннего сообщения о сдвиге',
  'Обещать точную дату при высокой неопределённости|Скрывать задержку до дедлайна|Путать занятость людей с завершённым результатом',
  'Что должно быть верно, чтобы прогноз сбылся?|При каком сигнале вы обновите обещание?');

add('planning','flow','Поток работы и ограничения','Снижать ожидание и незавершённую работу.',
  'Время от запроса до результата складывается из работы и ожидания. Часто задачи стоят в очереди на решение, ревью, тестирование или релиз дольше, чем разрабатываются. Много параллельной работы увеличивает переключения и затрудняет прогноз. Тимлид ищет узкое место системы и улучшает его вместе с командой.',
  'Отметьте состояния задач от запроса до выпуска и дату входа в каждое состояние.|Найдите самый длинный этап ожидания и причину блокировки.|Установите разумный предел одновременных задач и правило помощи заблокированным.|Проверьте через несколько недель время прохождения и качество результата.',
  'В работе было двенадцать задач на четырёх инженеров, а ревью ожидало по три дня. Команда стала сначала завершать начатое и выделила ежедневное окно ревью; срок прохождения сократился.',
  'Нарисуйте доску потока и опишите правило для заблокированной задачи, лимит одновременной работы и одно измерение эффекта.',
  'Показано время ожидания, а не только время кодирования|Есть правило для блокировок|Изменение проверяется на реальных завершённых задачах',
  'Повышать загрузку каждого человека до 100%|Начинать новое вместо завершения старого|Вводить лимит без учёта срочной поддержки',
  'Где задача ждёт больше всего?|Как команда поможет узкому месту?');

add('engineering','quality','Качество как рабочая договорённость','Общие критерии готовности и инженерные практики.',
  'Качество нельзя «добавить в конце». Команде нужны согласованные критерии готовности: корректное поведение, тесты, наблюдаемость, безопасность, документация и план выпуска в зависимости от риска. Критерии должны быть достаточно конкретными для проверки и достаточно гибкими для разных классов изменений. Тимлид помогает соблюдать их без формального театра.',
  'Опишите типы изменений: обычное, рискованное, экстренное.|Для каждого согласуйте минимальные проверки и ответственного за принятие риска.|Встройте проверки в обычный путь разработки: автоматические тесты, ревью, проверка миграций, мониторинг.|Разберите исключения после выпуска и улучшите правило, если оно не работает.',
  'Малое изменение текста проходит быстрый путь. Изменение платежей требует сценариев отказа, проверки идемпотентности, плана отката и наблюдения после релиза.',
  'Напишите определение готовности для двух типов задач: обычной функции и изменения критичного платежного потока.',
  'Проверки соразмерны риску|Ясно, кто разрешает исключение|Есть способ заметить проблему после выпуска',
  'Превращать чек-лист в самоцель|Отменять проверки под давлением без фиксации риска|Считать ревью заменой тестов',
  'Что означает «готово» для пользователя и эксплуатации?|Как проверить исключение после срочного релиза?');

add('engineering','reviews','Ревью и технические решения','Повышать качество без блокирования команды.',
  'Ревью проверяет корректность и распространяет знания, а не утверждает статус автора. Замечания должны отделять обязательную ошибку от предпочтения. Для спорных решений полезно заранее зафиксировать контекст, варианты, последствия и условие пересмотра. Тимлид организует процесс так, чтобы ожидание ревью не стало постоянной очередью.',
  'Договоритесь о размере изменения и времени ответа на ревью.|Проверяйте сначала поведение, безопасность и сопровождение; стиль автоматизируйте.|Сформулируйте замечание с причиной и предложением, помечайте необязательные идеи.|Для крупного выбора запишите короткое решение и сообщите, когда его стоит пересмотреть.',
  'Два инженера спорили о библиотеке. Вместо длинной переписки они сравнили требования, поддержку, стоимость миграции и сделали ограниченный пробный запуск. Решение осталось доступным следующей команде.',
  'Подготовьте шаблон ревью и короткую запись технического решения с контекстом, вариантами, выбором и последствиями.',
  'Есть правило сроков ревью|Обязательные и необязательные замечания различимы|Решение содержит условия пересмотра',
  'Использовать ревью для демонстрации превосходства|Навязывать личный стиль|Принимать решение без владельца и контекста',
  'Какие замечания блокируют выпуск?|Как новый сотрудник поймёт причину решения через полгода?');

add('engineering','debt','Технический долг и архитектура','Платить за риск там, где это улучшает поставку.',
  'Технический долг — не всякий некрасивый код. Полезно описать конкретное последствие: задержка изменений, дефекты, риск отказа или зависимость от человека. Архитектурный выбор должен соответствовать размеру команды и продуктовой задаче. Тимлид договаривается о времени на улучшения через понятную стоимость проблемы и проверяемый результат.',
  'Соберите примеры повторяющихся затрат: время релиза, дефекты, ручные операции, задержки новых функций.|Оцените частоту и ущерб, отделите факты от предположений.|Выберите минимальное улучшение, которое устранит причину, и свяжите его с планируемой работой.|Измерьте эффект после изменения и удалите устаревшие обходные пути.',
  'Команда хотела переписать весь сервис. Анализ показал, что основная задержка — ручная регрессия одного модуля. Сначала добавили автоматические сценарии и сократили время релиза.',
  'Создайте реестр из трёх элементов долга: симптом, цена, риск бездействия, возможное улучшение и способ измерения эффекта.',
  'Каждый пункт связан с наблюдаемой проблемой|Есть порядок по ущербу и усилию|Предложено небольшое первое действие',
  'Объявлять переписывание универсальным решением|Копить долг без видимого владельца|Считать новую технологию автоматическим улучшением',
  'Какая стоимость долга видна продукту?|Как доказать, что улучшение помогло?');

add('operations','service','Ответственность за сервис','Наблюдаемость, цели надёжности и дежурства.',
  'Команда отвечает за систему после выпуска. Для важных пользовательских сценариев нужны сигналы работоспособности: успешность, задержка и доступность. Цель надёжности помогает осознанно обменивать скорость изменений на риск. Дежурство должно иметь инструкции, понятный путь эскалации и нагрузку, которую можно выдержать.',
  'Выберите один критичный пользовательский сценарий и его показатель качества.|Определите целевое значение и сигнал, который разбудит дежурного только при значимом ущербе.|Составьте инструкцию: как проверить, локализовать, смягчить и кому сообщить.|Запланируйте ротацию и разберите нагрузку от дежурств на планировании.',
  'Вместо тревоги на каждую ошибку команда отслеживает долю неуспешных оплат. Если показатель быстро ухудшается, дежурный переключает поток на резервный маршрут и сообщает ответственным.',
  'Опишите один сервис: пользовательский сценарий, показатель, порог тревоги, первые пять действий дежурного и правило эскалации.',
  'Показатель отражает пользовательский опыт|Тревога требует действия|Инструкция понятна человеку вне основного контекста',
  'Будить людей по шумным сигналам|Считать эксплуатацию чужой задачей|Назначать одного постоянного дежурного',
  'Как узнать о проблеме раньше жалобы клиента?|Как проверить, что тревога действительно полезна?');

add('operations','incident','Управление инцидентом','Стабилизировать сервис и ясно сообщать о ходе работ.',
  'Во время сбоя приоритет — уменьшить ущерб, а не сразу найти идеальную причину. Нужны координатор, исполнитель технических действий, канал связи и регулярные обновления. Временное смягчение допустимо, если снижает риск; после восстановления команда исследует причину. Предположения о времени исправления следует обозначать как предположения.',
  'Объявите инцидент и назначьте координатора, даже если людей мало.|Опишите влияние на пользователей и зафиксируйте время начала, решения и наблюдения.|Проверьте безопасные действия: откат, отключение функции, переключение маршрута.|Сообщайте факты и следующий срок обновления; после восстановления подтвердите метрики и передайте остаточные задачи.',
  'После релиза выросло число отказов оплаты. Координатор остановил дополнительные изменения, инженер откатил релиз, поддержка получила короткое сообщение о затронутых заказах. Причину искали после восстановления.',
  'Напишите план первых 30 минут для отказа критичной функции: роли, канал связи, действия по смягчению и пример сообщения заинтересованным сторонам.',
  'Названы роли и владелец внешней коммуникации|Первые действия уменьшают ущерб|Сообщение содержит влияние, известные факты и время следующего обновления',
  'Искать виновного во время сбоя|Делать несколько рискованных изменений одновременно|Молчать до полного устранения причины',
  'Какое действие быстрее всего сократит ущерб?|Кто и когда получит следующее обновление?');

add('operations','postmortem','Разбор без обвинений','Превращать сбой в изменение системы работы.',
  'Хороший разбор реконструирует события и условия, при которых разумные действия людей привели к сбою. Он различает непосредственный триггер и системные причины: недостаточные тесты, неясное владение, слабые сигналы, сложный откат. Результат разбора — небольшое число конкретных действий с владельцами и проверкой, а не длинный список обещаний.',
  'Соберите временную шкалу из логов, сообщений и решений.|Опишите влияние, обнаружение, смягчение и восстановление без оценочных формулировок о людях.|Назовите условия, которые позволили сбою возникнуть и продлиться.|Выберите 1–3 улучшения, назначьте владельцев и даты проверки эффективности.',
  'Причиной задержки восстановления назвали не «инженер не заметил», а отсутствие тревоги по доле ошибок и слишком сложный откат. Команда добавила сигнал и проверила процедуру отката на тренировке.',
  'Напишите краткий разбор учебного инцидента: влияние, шкала времени, условия, что помогло, три действия и проверка их результата.',
  'Отделены факты и гипотезы|Действия устраняют условия, а не только напоминают быть внимательнее|У каждого действия есть владелец и проверка',
  'Искать одного виновного|Заканчивать разбор словом «быть осторожнее»|Оставлять действия без сроков',
  'Почему система позволила ошибке стать инцидентом?|Как через месяц проверить эффект изменений?');

add('people','one-on-one','Встречи один на один','Слушать, поддерживать и выявлять препятствия.',
  'Регулярная личная встреча — пространство сотрудника для обсуждения работы, мотивации, отношений и роста. Это не статус-отчёт по задачам. Тимлид задаёт открытые вопросы, уточняет факты, договаривается о действиях и возвращается к ним. Записи должны быть краткими, уважать приватность и не содержать лишних чувствительных деталей.',
  'Согласуйте периодичность и цель встреч с каждым человеком.|Дайте сотруднику первым назвать важные темы; спросите о нагрузке, препятствиях и ожиданиях.|Уточните наблюдения и предложите помощь, не решая всё вместо него.|Запишите только договорённости, владельцев и срок возврата; начните следующую встречу с них.',
  'Инженер говорит, что «не успевает». Лид не советует просто работать быстрее, а выясняет, что половину дня занимают незапланированные консультации. Они вводят время для вопросов и пересматривают нагрузку.',
  'Подготовьте повестку 30-минутной встречи: открывающие вопросы, обсуждение препятствия, договорённости и проверка прошлых обещаний.',
  'Разговор принадлежит сотруднику|Есть конкретная помощь или договорённость|Записи не превращаются в скрытую оценку человека',
  'Заменять встречу отчётом по тикетам|Отменять её при каждой срочной задаче|Обещать помощь и не возвращаться к вопросу',
  'Какие вопросы помогут человеку раскрыть проблему?|Какие договорённости вы проверите в следующий раз?');

add('people','feedback','Обратная связь и сложный разговор','Говорить о наблюдаемом поведении и его влиянии.',
  'Полезная обратная связь своевременна, конкретна и относится к поведению, которое можно изменить. Она описывает ситуацию, действие и последствия, затем приглашает вторую сторону объяснить контекст. Похвала также должна быть предметной. Если проблема повторяется, нужны ясные ожидания, помощь и дата пересмотра, а не намёки.',
  'Подготовьте два-три проверяемых примера без ярлыков о характере человека.|Назовите влияние на работу и желаемое поведение.|Спросите, как сотрудник видит ситуацию, и выслушайте контекст.|Согласуйте конкретный следующий шаг, необходимую поддержку и дату повторного разговора.',
  'Вместо «ты безответственный» лид говорит: «Два последних изменения ушли без согласованного теста, после этого команда дважды откатывала релиз. Что мешало проверить их и как изменим процесс?»',
  'Напишите сценарий разговора о повторяющемся срыве договорённости: факт, влияние, вопрос, ожидание, помощь и срок проверки.',
  'Нет оценок личности и домыслов о намерениях|Ожидание наблюдаемо|Есть место для ответа сотрудника и дальнейшая проверка',
  'Копить претензии месяцами|Говорить заочно через других|Путать доброжелательность с отсутствием ясных ожиданий',
  'Что вы действительно наблюдали?|Как человек поймёт, что ситуация улучшилась?');

add('people','growth','Развитие и устойчивость нагрузки','Растить компетенции через работу и беречь ресурс команды.',
  'Развитие не сводится к списку курсов. Человек растёт на подходящих задачах, получает своевременную обратную связь и пространство для рефлексии. Карьерная цель принадлежит сотруднику; лидер помогает найти возможности и честно показывает требования роли. Устойчивая нагрузка важнее краткого героического рывка: регулярные переработки сигнализируют о проблеме планирования.',
  'Обсудите интересы человека, сильные стороны и следующий навык, который действительно нужен работе.|Выберите одну задачу чуть выше текущего уровня и обозначьте поддержку.|Договоритесь о наблюдаемом результате и регулярной обратной связи.|Проверяйте нагрузку, отпуск, дежурства и признаки постоянного перенапряжения; при необходимости меняйте объём работы.',
  'Разработчик хочет стать ведущим инженером. Вместо абстрактного «проявляй лидерство» он ведёт небольшое техническое решение, помогает коллеге и презентует последствия выбора команде.',
  'Составьте план развития на шесть недель: навык, рабочая возможность, поддержка, доказательство роста и проверка нагрузки.',
  'Цель согласована с сотрудником|Есть работа для практики навыка|Указаны частота обратной связи и сигнал перегрузки',
  'Навязывать всем управленческий путь|Обещать повышение без полномочий|Называть постоянные переработки мотивацией',
  'Как человек применит навык в работе?|Что вы измените, если план перегружает его?');

add('hiring','role-profile','Профиль роли и решение о найме','Нанимать под реальную задачу команды.',
  'Вакансия начинается с проблемы, которую новый человек должен помочь решить, а не с перечня модных технологий. Разделяйте обязательные навыки и то, чему можно научиться. Определите уровень ответственности и условия успеха через несколько месяцев. Если проблема решается изменением процесса или временной помощью, найм может оказаться не лучшим первым действием.',
  'Опишите потребность команды и альтернативы найму.|Укажите задачи первых месяцев и самостоятельные решения, ожидаемые от роли.|Выделите 3–5 обязательных компетенций и отдельно желательные.|Согласуйте профиль, бюджет и процесс отбора с участниками найма.',
  'Команде нужен человек, способный вести интеграции и обсуждать требования с партнёрами. Опыт конкретного фреймворка полезен, но не является обязательным требованием.',
  'Напишите профиль вакансии: проблема, результат через 3 и 6 месяцев, обязательные навыки, что команда готова обучить и критерии успешного найма.',
  'Требования связаны с задачами|Обязательный список короткий|Есть критерий успеха после выхода человека',
  'Копировать чужую вакансию|Искать «универсального героя»|Завышать уровень ради подстраховки',
  'Какой пробел закрывает роль?|Какие навыки можно освоить после найма?');

add('hiring','interview','Структурированное интервью','Сравнивать кандидатов по одинаковым сигналам.',
  'Интервью должно собирать доказательства навыков, нужных роли, а не впечатление от сходства с командой. Используйте одинаковые ключевые вопросы, заранее определённые критерии и независимые заметки интервьюеров. Практическое задание должно быть соразмерно роли и уважать время кандидата. Личные и защищённые характеристики не относятся к оценке профессиональных навыков.',
  'Для каждой компетенции определите наблюдаемое поведение и подходящий вопрос или задачу.|Проведите интервью по общей структуре, задавайте уточнения о действиях кандидата.|Сразу после встречи запишите факты отдельно от интерпретаций.|На совместном обсуждении сравните доказательства с профилем роли, отметьте пробелы и способ их проверки.',
  'На вопрос о сбое один кандидат подробно рассказал, как снизил ущерб, организовал связь и изменил процесс. Это сильнее общего заявления «я хорошо работаю в стрессе».',
  'Создайте карточку интервью для трёх компетенций: вопрос, сильный и слабый сигнал, место для фактов и итоговая оценка с обоснованием.',
  'Вопросы проверяют требования роли|Факты отделены от симпатии|Решение можно объяснить по доказательствам',
  'Оценивать по «культурному совпадению» без критериев|Менять планку для разных кандидатов|Делать длинное неоплачиваемое задание по реальной работе компании',
  'Какие факты доказывают компетенцию?|Как вы уменьшите влияние первого впечатления?');

add('hiring','onboarding','Адаптация нового сотрудника','Дать контекст, первые победы и безопасный путь к самостоятельности.',
  'Успешный выход человека зависит от доступа к знаниям, ясных ожиданий, отношений и обратной связи. Документация не заменяет сопровождающего коллегу. Первые задачи должны быть небольшими и настоящими; затем ответственность растёт. Скорость адаптации отличается, поэтому план проверяют по результатам, а не по жёсткому числу дней.',
  'Подготовьте доступы, окружение, карту продукта и контакты до первого дня.|Назначьте сопровождающего и запланируйте регулярные короткие вопросы.|Дайте первую ограниченную задачу с ясным критерием готовности и обратной связью.|На 2-й, 4-й и 8-й неделе обсудите понимание системы, самостоятельность и препятствия; адаптируйте план.',
  'Новый инженер начинает с небольшого исправления, проходит путь ревью и релиза с напарником, затем самостоятельно ведёт одну функцию. Каждый шаг расширяет знакомство с системой.',
  'Сделайте план первого дня, первой недели и первых двух месяцев: доступы, люди, задачи, обратная связь и критерии самостоятельности.',
  'Первый результат достижим и полезен|Есть конкретный сопровождающий|План содержит встречи для проверки взаимных ожиданий',
  'Оставлять новичка один на один с устаревшей документацией|Оценивать продуктивность в первые дни как у старожила|Назначать только учебные задачи без контекста',
  'Как новичок поймёт, что движется правильно?|Какие препятствия вы должны убрать заранее?');

add('communication','stakeholders','Карта заинтересованных сторон','Выстроить ожидания и регулярный обмен информацией.',
  'На команду влияют продукт, дизайн, поддержка, безопасность, эксплуатация и руководство. У каждого разные потребности в информации и разные полномочия. Тимлид выясняет, кто принимает решение, кого нужно консультировать и кому достаточно сообщить итог. Ритм обновлений снижает внезапные запросы и делает проблемы видимыми до дедлайна.',
  'Составьте список людей и групп, которые влияют на работу или зависят от неё.|Для каждого запишите интерес, решение, нужную частоту и формат связи.|Договоритесь о канале для рисков и изменении планов.|После важного решения отправьте краткое резюме: что решили, почему, кто делает следующий шаг.',
  'Поддержка узнавала о новых функциях только после жалоб клиентов. Команда добавила короткое сообщение перед релизом с изменением поведения и известными ограничениями.',
  'Создайте карту минимум шести сторон для учебного продукта: интерес, полномочие, формат обновления и правило эскалации.',
  'Указан владелец ключевых решений|Частота связи соответствует риску|Есть способ быстро поднять проблему',
  'Уведомлять всех одинаково длинным отчётом|Держать риск до следующего статусного совещания|Путать информирование с согласованием',
  'Кто может остановить решение?|Кому нужно знать о риске сегодня?');

add('communication','conflict','Разрешение конфликта','Работать с интересами, фактами и договорённостями.',
  'Конфликт часто возникает из-за несовпадающих целей, неполной информации или неясного права решения. Лид не должен объявлять одну сторону «сложной». Сначала нужно обеспечить уважительный разговор, выяснить факты и интересы, затем согласовать правила или эскалировать решение тому, у кого есть полномочия. Личные нападения и нарушения границ требуют отдельной реакции.',
  'Поговорите с участниками отдельно и соберите конкретные наблюдения.|На общей встрече назовите общую цель и правила уважительного обсуждения.|Попросите каждую сторону объяснить потребность и предложить варианты.|Зафиксируйте решение, владельца, срок проверки и путь эскалации, если соглашение не сработает.',
  'Разработчик хочет сократить тесты ради срока, тестировщик требует полный прогон. Выясняется, что риск касается только платежного сценария. Они договариваются о полном прогоне там и быстром наборе проверок для остальных изменений.',
  'Подготовьте сценарий разговора между двумя участниками с противоположными позициями: факты, интересы, варианты и проверка договорённости.',
  'Обе стороны получили возможность объяснить интересы|Решение связано с общей целью|Есть дата проверки и маршрут эскалации',
  'Проводить «суд» без фактов|Требовать компромисс там, где есть нарушение безопасности или уважения|Оставлять устную договорённость без владельца',
  'Какие интересы скрываются за позициями?|Кто вправе принять решение при отсутствии согласия?');

add('communication','written','Письменная коммуникация','Делать решения и состояние работы понятными.',
  'Хорошее сообщение позволяет читателю быстро понять контекст, решение, последствия и требуемое действие. Формат зависит от аудитории: для команды нужны детали исполнения, для руководителя — результат, риск и выбор. Асинхронная запись снижает потери информации, но важные эмоциональные темы лучше обсуждать лично. После устной встречи полезно оставить короткое резюме.',
  'Начните сообщение с вывода и адресата действия.|Добавьте необходимые факты, влияние, альтернативы и срок ответа.|Разделите подтверждённое и предположения; укажите владельца следующего шага.|Проверьте, может ли новый читатель понять решение без длинной переписки.',
  'Вместо «мы задерживаемся» лид пишет: «Первый релиз сдвигается на неделю из-за изменения API партнёра. Можно сохранить дату, исключив возвраты. Решение по объёму нужно до четверга».',
  'Напишите два сообщения об одном риске: короткое для руководителя и рабочее для команды. В обоих укажите требуемое решение.',
  'Вывод стоит в начале|Факты и предположения разделены|Читателю ясно, что сделать и когда',
  'Прятать плохую новость в длинном тексте|Публиковать решение без последствий|Вести сложный личный разговор только в чате',
  'Что читатель должен сделать после сообщения?|Какие детали нужны именно этой аудитории?');

add('decisions','delegation','Делегирование с контекстом','Передавать решение вместе с правами и поддержкой.',
  'Делегирование — не сбрасывание задачи. Человеку нужны цель, границы, право выбора, доступ к информации и контрольная точка. Уровень самостоятельности зависит от риска и опыта; его можно повышать постепенно. Тимлид остаётся ответственным за систему работы, но не подменяет владельца на каждом шаге.',
  'Выберите задачу, которая развивает человека и не требует вашего постоянного участия.|Опишите желаемый результат, ограничения, критерий качества и полномочия.|Согласуйте дату проверки и ситуации, когда нужна эскалация.|Оцените результат вместе, дайте обратную связь и расширьте автономию при успехе.',
  'Инженеру поручили выбор библиотеки логирования. Лид обозначил требования безопасности, бюджет времени и обязанность обсудить миграцию с эксплуатацией, но не назначил заранее любимый вариант.',
  'Подготовьте карточку делегирования: результат, ограничения, свобода решения, доступная помощь, контрольная точка и условия эскалации.',
  'У исполнителя есть право принимать названные решения|Критерии результата проверяемы|Контрольная точка не превращается в ежедневное вмешательство',
  'Передавать задачу без полномочий|Возвращать себе решение при первом несогласии|Считать делегирование способом избавиться от неудобной работы',
  'Что человек вправе решить без вас?|Когда вы должны вмешаться?');

add('decisions','decision-record','Принятие и фиксация решений','Выбирать вариант при неполной информации.',
  'Решение хорошее, если учитывает доступные факты, ограничения и последствия, даже когда будущий результат неизвестен. Обратимые решения можно принимать быстро с проверкой. Труднообратимые требуют более тщательного обсуждения и явного владельца. Запись решения сохраняет контекст для новых людей и помогает вовремя пересмотреть выбор.',
  'Сформулируйте проблему и дедлайн выбора.|Соберите критерии, ограничения и 2–3 реальных варианта.|Оцените пользу, цену, риск и обратимость каждого; назовите неизвестное.|Назначьте владельца, примите решение, сообщите его и запишите сигнал для пересмотра.',
  'Команда выбирала очередь сообщений. Она сравнила текущий объём, требования к доставке, операционные затраты и простоту отката. Выбрала существующий инструмент и оставила условие пересмотра при росте нагрузки.',
  'Запишите одно решение на страницу: контекст, варианты, критерии, выбор, последствия, владелец и условие пересмотра.',
  'Есть реальные альтернативы|Последствия и неопределённость названы|Понятно, кто и когда пересмотрит решение',
  'Ждать абсолютной уверенности|Выбирать технологию по популярности|Не сообщать решение людям, которых оно касается',
  'Насколько решение обратимо?|Что заставит вас изменить выбор?');

add('decisions','meetings','Встречи, ритуалы и полномочия','Оставить только встречи, которые помогают работе.',
  'Встреча оправдана, когда совместный разговор ускоряет решение, координацию или обучение. У каждой встречи должны быть цель, участники, материалы и ожидаемый выход. Статус часто можно передать письменно; спор, риск и сложная развилка требуют диалога. Права принятия решений важно назвать заранее, иначе встреча закончится без результата.',
  'Проведите аудит регулярных встреч: цель, стоимость времени, результат последних встреч.|Для каждой решите: оставить, изменить, заменить асинхронным обновлением или убрать.|В приглашении укажите вопрос, материалы и владельца решения.|После встречи зафиксируйте решение, действия, владельцев и дату проверки.',
  'Ежедневный часовой статус заменили коротким письменным обновлением и 15-минутным обсуждением блокировок. Освободившееся время пошло на совместную работу над сложными задачами.',
  'Переработайте одну типовую встречу: зачем она нужна, кто участвует, как готовиться, какой результат и как измерить её полезность.',
  'Для встречи указан ожидаемый выход|Состав участников соответствует решению|Действия после встречи имеют владельцев',
  'Созывать всех «на всякий случай»|Использовать ретроспективу как отчёт руководителю|Заканчивать без решения или следующего шага',
  'Можно ли решить вопрос письменно?|Кто уполномочен принять итоговое решение?');

add('metrics','signals','Метрики команды','Измерять поток, качество и здоровье вместе.',
  'Одна цифра не описывает эффективность команды. Смотрите на несколько сигналов: время прохождения задачи, объём незавершённого, частоту выпуска, дефекты, надёжность и устойчивость нагрузки. Интерпретируйте их в контексте: высокая частота релизов бесполезна при частых откатах. Индивидуальные числовые рейтинги обычно искажают поведение и скрывают совместную работу.',
  'Выберите вопрос, на который нужна метрика, например «где задачи ждут?».|Определите источник данных, период и ограничения измерения.|Смотрите на тренд вместе с качественными наблюдениями команды и пользователей.|При изменении процесса заранее назовите ожидаемый сигнал и проверяйте побочные эффекты.',
  'После уменьшения числа параллельных задач время поставки упало, но выросло ожидание у поддержки. Команда не объявила победу по одной цифре, а настроила отдельный поток срочных запросов.',
  'Соберите панель из пяти сигналов для учебной команды: вопрос, источник, период, полезная интерпретация и возможное искажение.',
  'Метрики отвечают на вопросы, а не украшают отчёт|Есть баланс скорости и качества|Названы способы искажения каждой цифры',
  'Сравнивать людей по строкам кода или числу задач|Устанавливать цель без базового уровня|Скрывать плохие данные ради красивого графика',
  'Какое решение изменит эта метрика?|Как люди могут начать оптимизировать цифру в ущерб результату?');

add('metrics','retrospective','Ретроспектива и эксперименты','Улучшать способ работы небольшими проверками.',
  'Ретроспектива полезна, когда команда безопасно обсуждает наблюдения и выбирает конкретное изменение. Нужны данные, разные голоса и последующая проверка. Много пунктов без владельцев создают ощущение деятельности, но не меняют работу. Эксперимент лучше формулировать как гипотезу с ограниченным сроком и сигналом эффекта.',
  'Покажите факты периода: завершённые результаты, ожидания, инциденты, нагрузку.|Соберите наблюдения каждого человека без поиска виновных.|Выберите одну проблему, на которую команда может повлиять, и сформулируйте гипотезу.|Назначьте владельца эксперимента, срок и критерий; следующую встречу начните с проверки.',
  'Команда заметила долгие ревью. Она на две недели ввела правило раннего запроса ревью и ежедневный короткий слот. Затем сравнила время ожидания и отзывы участников.',
  'Подготовьте сценарий ретроспективы на 45 минут и карточку одного эксперимента: проблема, гипотеза, действие, владелец, срок и проверка.',
  'Есть безопасный сбор мнений|Выбран один выполнимый эксперимент|Назначены дата и критерий проверки',
  'Превращать встречу в поиск виновного|Фиксировать десятки улучшений без ресурсов|Каждый раз повторять одни и те же проблемы',
  'На что команда реально может повлиять?|Как проверить, что эксперимент помог?');

add('metrics','health','Здоровье команды и устойчивый темп','Рано замечать перегрузку и системные помехи.',
  'Усталость, текучесть и молчание на встречах часто проявляются раньше падения поставки. Но опросы нельзя использовать как инструмент контроля отдельных людей. Сочетайте анонимные сигналы с добровольными разговорами, наблюдениями о дежурствах и переработках. Если люди открывают проблему, лидер должен показать действие или честно объяснить ограничения.',
  'Определите несколько вопросов о ясности целей, нагрузке, безопасности обсуждения и возможности сосредоточиться.|Соберите ответы способом, который уважает приватность, и обсудите общую картину.|Проверьте реальные источники перегрузки: срочные задачи, инциденты, зависимость от одного человека.|Уберите или перераспределите работу и договоритесь, когда команда оценит эффект.',
  'Опрос показал снижение возможности сосредоточиться. Разговоры выявили поток прямых сообщений от смежников. Лид договорился об одном канале входящих запросов и времени ответа.',
  'Составьте четыре вопроса о здоровье команды и план действий при устойчивом ухудшении двух сигналов.',
  'Вопросы не раскрывают чувствительные данные отдельного человека|Есть конкретное действие на системную причину|Команда узнает, что произошло с результатами',
  'Собирать ответы и ничего не менять|Диагностировать человека по одному опросу|Подменять разговоры метрикой настроения',
  'Какая рабочая причина может стоять за сигналом?|Как сообщить команде о действиях после опроса?');

add('organization','dependencies','Зависимости между командами','Делать внешние ожидания явными.',
  'Зависимости создают риск, если у двух команд разные планы, владельцы и определения готовности. Не достаточно записать «ждём другую команду»: нужно согласовать контракт, дату, способ проверки и запасной вариант. Регулярные короткие синхронизации помогают до тех пор, пока не заменяют ясную ответственность.',
  'Для каждой внешней зависимости запишите результат, владельца и дату, когда он нужен.|Согласуйте интерфейс, критерий приёмки и способ проверки на раннем примере.|Выявите критический путь и вариант, если зависимость задержится.|Поднимайте риск до срока, когда ещё можно изменить объём или последовательность.',
  'Мобильная команда ждёт API. Вместо ожидания готового сервера обе команды согласовали контракт и тестовый ответ, после чего работали параллельно. Изменения контракта обсуждали отдельно.',
  'Составьте реестр зависимостей для проекта из трёх команд: результат, владелец, срок, проверка, риск и запасной план.',
  'Каждая зависимость имеет конкретный результат|Есть ранняя проверка совместимости|Запасной план подготовлен до критической даты',
  'Считать чужую задачу чужим риском|Согласовывать только календарную дату без интерфейса|Эскалировать в последний день',
  'Что блокирует критический путь?|Как работать параллельно безопасно?');

add('organization','budget','Ресурсы и экономика решений','Сравнивать стоимость команды, инфраструктуры и задержки.',
  'Бюджет тимлида может ограничиваться людьми, инфраструктурой и временем. Даже если финансовое решение принимает другой руководитель, лид должен уметь объяснить цену вариантов: стоимость эксплуатации, миграции, поддержки и промедления. Считать нужно диапазонами и допущениями, избегая ложной точности. Деньги — один из критериев наряду с риском и пользовательской ценностью.',
  'Определите доступные люди и время, расходы на сервисы и важные ограничения.|Для каждого варианта посчитайте не только запуск, но и дальнейшую поддержку.|Назовите стоимость задержки результата и риск неожиданных расходов.|Представьте руководителю варианты с диапазоном затрат, выгодой и условиями пересмотра.',
  'Новый внешний сервис снижает труд разработки на месяц, но требует постоянной оплаты и создаёт зависимость от поставщика. Решение сравнивают на горизонте года, включая выход и поддержку.',
  'Сравните два решения для одной проблемы: люди/недели, расходы на инфраструктуру, операционная цена, риск и момент пересмотра.',
  'Учтены разовые и регулярные затраты|Допущения видны|Решение связано с ценностью и риском, а не одной ценой',
  'Считать время инженеров бесплатным|Сравнивать варианты на разных горизонтах|Скрывать неопределённость за точной суммой',
  'Какова полная цена решения за год?|Что произойдёт при задержке на месяц?');

add('organization','quarter','Квартальный план и изменения','Связать цели, возможности и реальную мощность.',
  'Квартальный план — набор ставок с явными ограничениями, а не список всех желаний. Он должен включать продуктовую работу, надёжность, обязательства, обучение и резерв на непредвиденное. При изменении условий лид объясняет, что меняется в объёме, сроках или ресурсах. План полезен, когда его регулярно пересматривают по новым фактам.',
  'Выберите 2–3 результата квартала и показатель для каждого.|Оцените мощность команды с учётом отпусков, дежурств, поддержки и развития.|Разбейте результаты на контрольные точки и укажите внешние зависимости.|На ежемесячном обзоре проверьте факты, риски и явно перенесите работу, которая не помещается.',
  'Команда запланировала новый кабинет, снижение ошибок оплаты и поддержку старого API. После первого месяца выяснился большой объём обращений. Лид сократил первый релиз кабинета, сохранив две критичные цели.',
  'Напишите квартальный план: три результата, контрольные точки, распределение мощности, резерв, зависимости и правило пересмотра.',
  'План помещается в доступную мощность|Есть место для поддержки и риска|Приоритеты позволяют осмысленно сократить объём',
  'Заполнять квартал на 100% предполагаемой мощности|Называть список функций результатами|Менять план без сообщения последствий',
  'Что вы уберёте при росте внеплановой работы?|Как поймёте, что квартальная цель достигнута?');

add('leadership','pressure','Лидерство под давлением','Сохранять ясность, границы и качество решений.',
  'Давление срока, инцидента или руководителя сужает внимание и провоцирует скрывать риск. Тимлид возвращает разговор к фактам, вариантам и последствиям. Он может поддержать команду, не обещая невозможного: назвать ограничение, предложить уменьшить объём или изменить дату. После напряжённого периода важно восстановить устойчивый режим работы.',
  'Назовите факты, неизвестное и самое срочное решение.|Соберите 2–3 допустимых варианта с последствиями для срока, качества и людей.|Укажите границы, которые нельзя нарушать: безопасность, закон, критичные проверки.|Сообщите решение, владельцев и следующий момент пересмотра; после кризиса разберите нагрузку.',
  'Руководитель просит выпустить весь функционал к пятнице. Лид показывает два безопасных варианта: ограниченный релиз в пятницу или полный на следующей неделе. Команда не скрывает риск тестирования.',
  'Напишите ответ на нереалистичное требование: подтверждённые факты, два варианта, последствия и решение, которое нужно от заказчика.',
  'Ответ содержит варианты, а не только отказ|Границы безопасности явны|Команда получает решение и срок пересмотра',
  'Перекладывать давление на команду без изменения плана|Скрывать риск ради спокойствия|Считать разовый героизм рабочей нормой',
  'Какую развилку должен решить заказчик?|Какая цена у каждого варианта?');

add('leadership','difficult','Низкая результативность и расставание','Действовать справедливо, последовательно и с уважением.',
  'Повторяющееся несоответствие ожиданиям требует конкретных фактов и поддержки, а не публичной оценки личности. Проверьте, были ли цели ясными, хватало ли доступа и не мешали ли системные условия. Если улучшения нет, действуйте по правилам компании и совместно с уполномоченным руководителем или HR. Трудовые решения зависят от местного права и полномочий роли; тимлид не должен обещать исход, который не контролирует.',
  'Соберите факты о рабочих результатах и ранее согласованных ожиданиях.|Обсудите их с человеком конфиденциально, выслушайте причины и уточните помощь.|Согласуйте измеримые изменения, разумный срок и регулярные проверки.|Если результата нет, подключите ответственных за кадровое решение, соблюдайте процесс и защищайте достоинство человека.',
  'Инженер регулярно выпускает изменения без необходимых проверок. Лид уточняет ожидание, даёт время и поддержку для освоения процесса, фиксирует изменения. При повторении проблемы решение принимает по официальной процедуре с HR.',
  'Составьте план разговора и поддержки на четыре недели: факты, ожидания, ресурсы, проверки и границы ваших полномочий.',
  'Основание состоит из наблюдаемых фактов|Человеку доступна помощь и ясный срок|Кадровые действия переданы уполномоченным лицам',
  'Обсуждать проблему с коллегами за спиной человека|Откладывать разговор до формальной оценки|Самостоятельно импровизировать юридически значимые процедуры',
  'Были ли ожидания понятны заранее?|Что в ситуации относится к системе работы, а что к индивидуальному поведению?');

add('leadership','successor','Преемственность и личное развитие','Создать команду, которая справляется без постоянного участия лида.',
  'Зрелость тимлида видна в том, что знания, полномочия и отношения не сосредоточены в одном человеке. Лид развивает людей, передаёт контекст и проверяет, может ли команда принимать решения во время его отсутствия. Собственное развитие тоже требует обратной связи: от команды, руководителя и партнёров по продукту. Следующая роль не обязана быть менеджерской; возможен возврат к технической специализации.',
  'Составьте карту решений и знаний, которые зависят только от вас.|Выберите человека или группу для постепенной передачи каждого вида ответственности.|Проведите тренировку отсутствия: заранее задайте границы, затем наблюдайте без вмешательства.|Запросите обратную связь о своём влиянии и составьте личный план на следующий квартал.',
  'Перед отпуском лид передал инженеру ведение планирования, продакту — маршрут эскалации приоритетов, а дежурным — контакты и инструкции. После отпуска команда разобрала, где всё ещё требовался его ответ.',
  'Создайте план преемственности на месяц и личный план развития: три зависимости от вас, действия по передаче, обратная связь и проверка результата.',
  'У ключевых решений есть замена|Передача проверена практикой|Личный план основан на обратной связи, а не догадках',
  'Сохранять исключительное знание ради незаменимости|Называть делегирование уходом от ответственности|Игнорировать собственные пределы и восстановление',
  'Какие решения остановятся без вас?|Какую обратную связь о своём лидерстве вы готовы проверить действием?');

